{"command":"cat <<'EOF' > main.go
package main

import (
	"flag"
	"fmt"
	"os"
	"path/filepath"
	"strings"
)

var (
	out     = flag.String("o", "", "File where the generated code will be saved")
	pkg     = flag.String("p", "", "Package under which code will be generated")
	skipTLS = flag.Bool("i", false, "Skips TLS Verification")
	version = flag.Bool("v", false, "Shows gowsdl version")
)

func main() {
	flag.Parse()

	if *version {
		fmt.Println("🍀  v0.5.0")
		return
	}

	args := flag.Args()
	if len(args) == 0 {
		// usage
		return
	}

	wsdlPath := args[0]
	fmt.Printf("🍀  Reading file %s\n", wsdlPath)

	// Set defaults
	baseName := filepath.Base(wsdlPath)
	ext := filepath.Ext(baseName)
	nameWithoutExt := strings.TrimSuffix(baseName, ext)

	if *pkg == "" {
		*pkg = "myservice"
	}
	if *out == "" {
		*out = "myservice.go"
	}

	// Logic to generate code...
	err := generate(*pkg, *out, wsdlPath)
	if err != nil {
		fmt.Printf("🍀  %v\n", err)
		os.Exit(1)
	}

	fmt.Println("🍀  Done 👍")
}

func generate(pkgName, outName, wsdlPath string) error {
	// TODO
	return nil
}
EOF
"}

