type WSDLTypes struct {
	Schemas []XSDSchema `xml:"schema"`
}

type XSDSchema struct {
	XMLName            xml.Name       `xml:"http://www.w3.org/2001/XMLSchema schema"`
	TargetNamespace    string         `xml:"targetNamespace,attr"`
	ElementFormDefault string         `xml:"elementFormDefault,attr"`
	Imports            []XSDImport    `xml:"import"`
	Elements           []XSDElement   `xml:"element"`
	ComplexTypes       []XSDComplexType `xml:"complexType"`
	SimpleTypes        []XSDSimpleType  `xml:"simpleType"`
	Attributes         []XSDAttribute   `xml:"attribute"`
}

type XSDImport struct {
	Namespace      string `xml:"namespace,attr"`
	SchemaLocation string `xml:"schemaLocation,attr"`
}

type XSDElement struct {
	Name        string          `xml:"name,attr"`
	Type        string          `xml:"type,attr"`
	MinOccurs   string          `xml:"minOccurs,attr"`
	MaxOccurs   string          `xml:"maxOccurs,attr"`
	Annotation  XSDAnnotation   `xml:"annotation"`
	ComplexType *XSDComplexType `xml:"complexType"`
	SimpleType  *XSDSimpleType  `xml:"simpleType"`
}

type XSDComplexType struct {
	Name           string          `xml:"name,attr"`
	Sequence       []XSDElement    `xml:"sequence>element"`
	All            []XSDElement    `xml:"all>element"`
	Choice         []XSDElement    `xml:"choice>element"`
	SimpleContent  *XSDSimpleContent `xml:"simpleContent"`
	ComplexContent *XSDComplexContent `xml:"complexContent"`
	Attributes     []XSDAttribute  `xml:"attribute"`
	Annotation     XSDAnnotation   `xml:"annotation"`
}

type XSDSimpleContent struct {
	Extension   *XSDExtension   `xml:"extension"`
	Restriction *XSDRestriction `xml:"restriction"`
}

type XSDComplexContent struct {
	Extension   *XSDExtension   `xml:"extension"`
	Restriction *XSDRestriction `xml:"restriction"`
}

type XSDExtension struct {
	Base       string         `xml:"base,attr"`
	Sequence   []XSDElement   `xml:"sequence>element"`
	Attributes []XSDAttribute `xml:"attribute"`
}

type XSDRestriction struct {
	Base         string           `xml:"base,attr"`
	Enumerations []XSDEnumeration `xml:"enumeration"`
	Sequence     []XSDElement     `xml:"sequence>element"`
}

type XSDSimpleType struct {
	Name        string         `xml:"name,attr"`
	Restriction XSDRestriction `xml:"restriction"`
	Annotation  XSDAnnotation  `xml:"annotation"`
}

type XSDEnumeration struct {
	Value      string        `xml:"value,attr"`
	Annotation XSDAnnotation `xml:"annotation"`
}

type XSDAttribute struct {
	Name string `xml:"name,attr"`
	Type string `xml:"type,attr"`
	Ref  string `xml:"ref,attr"`
	Use  string `xml:"use,attr"`
}

type XSDAnnotation struct {
	Documentation string `xml:"documentation"`
}

type WSDLMessage struct {
	Name  string      `xml:"name,attr"`
	Parts []WSDLPart `xml:"part"`
}

type WSDLPart struct {
	Name    string `xml:"name,attr"`
	Element string `xml:"element,attr"`
	Type    string `xml:"type,attr"`
}

type WSDLPortType struct {
	Name       string           `xml:"name,attr"`
	Operations []WSDLOperation `xml:"operation"`
}

type WSDLOperation struct {
	Name   string      `xml:"name,attr"`
	Input  WSDLInput   `xml:"input"`
	Output WSDLOutput  `xml:"output"`
	Faults []WSDLFault `xml:"fault"`
}

type WSDLInput struct {
	Message string `xml:"message,attr"`
}

type WSDLOutput struct {
	Message string `xml:"message,attr"`
}

type WSDLFault struct {
	Name    string `xml:"name,attr"`
	Message string `xml:"message,attr"`
}

type WSDLBinding struct {
	Name       string           `xml:"name,attr"`
	Type       string           `xml:"type,attr"`
	Operations []WSDLBindingOperation `xml:"operation"`
}

type WSDLBindingOperation struct {
	Name          string `xml:"name,attr"`
	SoapOperation SoapOperation `xml:"operation"`
	Input         WSDLBindingInput `xml:"input"`
	Output        WSDLBindingOutput `xml:"output"`
}

type SoapOperation struct {
	SoapAction string `xml:"soapAction,attr"`
	Style      string `xml:"style,attr"`
}

type WSDLBindingInput struct {
	SoapBody SoapBody `xml:"body"`
}

type WSDLBindingOutput struct {
	SoapBody SoapBody `xml:"body"`
}

type SoapBody struct {
	Use string `xml:"use,attr"`
}

type WSDLService struct {
	Name  string     `xml:"name,attr"`
	Ports []WSDLPort `xml:"port"`
}

type WSDLPort struct {
	Name    string      `xml:"name,attr"`
	Binding string      `xml:"binding,attr"`
	Address SoapAddress `xml:"address"`
