	fmt.Fprintf(w, "type SOAPBodyRequest struct {\n\tXMLName xml.Name `xml:\"http://schemas.xmlsoap.org/soap/envelope/ Body\"`\n")
	for _, pt := range g.WSDL.PortTypes {
		for _, op := range pt.Operations {
			reqType := g.getMessageElement(op.Input.Message)
			fmt.Fprintf(w, "\n\t%s *%s `xml:\",omitempty\"`\n", reqType, reqType)
		}
	}
	fmt.Fprintf(w, "}\n\n")

	fmt.Fprintf(w, "type SOAPEnvelopeResponse struct {\n\tXMLName    xml.Name `xml:\"soap:Envelope\"`\n\tPrefixSoap string   `xml:\"xmlns:soap,attr\"`\n\tPrefixXsi  string   `xml:\"xmlns:xsi,attr\"`\n\tPrefixXsd  string   `xml:\"xmlns:xsd,attr\"`\n\n\tBody SOAPBodyResponse\n}\n\n")
	fmt.Fprintf(w, "func NewSOAPEnvelopResponse() *SOAPEnvelopeResponse {\n\treturn &SOAPEnvelopeResponse{\n\t\tPrefixSoap: \"http://schemas.xmlsoap.org/soap/envelope/\",\n\t\tPrefixXsd:  \"http://www.w3.org/2001/XMLSchema\",\n\t\tPrefixXsi:  \"http://www.w3.org/2001/XMLSchema-instance\",\n\t}\n}\n\n")
	fmt.Fprintf(w, "type Fault struct {\n\tXMLName xml.Name `xml:\"SOAP-ENV:Fault\"`\n\tSpace   string   `xml:\"xmlns:SOAP-ENV,omitempty,attr\"`\n\n\tCode   string `xml:\"faultcode,omitempty\"`\n\tString string `xml:\"faultstring,omitempty\"`\n\tActor  string `xml:\"faultactor,omitempty\"`\n\tDetail string `xml:\"detail,omitempty\"`\n}\n\n")

	fmt.Fprintf(w, "type SOAPBodyResponse struct {\n\tXMLName xml.Name `xml:\"soap:Body\"`\n\tFault   *Fault   `xml:\",omitempty\"`\n")
	for _, pt := range g.WSDL.PortTypes {
		for _, op := range pt.Operations {
			reqName := g.getMessageElement(op.Input.Message)
			respType := g.getMessageElement(op.Output.Message)
			fmt.Fprintf(w, "\n\t%s *%s `xml:\",omitempty\"`\n", reqName, respType)
		}
	}
	fmt.Fprintf(w, "}\n\n")

	for _, pt := range g.WSDL.PortTypes {
		for _, op := range pt.Operations {
			reqType := g.getMessageElement(op.Input.Message)
			respType := g.getMessageElement(op.Output.Message)
			fmt.Fprintf(w, "func (service *SOAPBodyRequest) %sFunc(request *%s) (*%s, error) {\n\treturn nil, WSDLUndefinedError\n}\n\n", reqType, reqType, respType)
		}
	}

	fmt.Fprintf(w, "func (service *SOAPEnvelopeRequest) call(w http.ResponseWriter, r *http.Request) {\n\tw.Header().Add(\"Content-Type\", \"text/xml; charset=utf-8\")\n\tval := reflect.ValueOf(&service.Body).Elem()\n\tn := val.NumField()\n\tvar field reflect.Value\n\tvar name string\n\tfind := false\n\n\tif r.Method == http.MethodGet {\n\t\tw.Write([]byte(wsdl))\n\t\treturn\n\t}\n\n\tresp := NewSOAPEnvelopResponse()\n\tdefer func() {\n\t\tif r := recover(); r != nil {\n\t\t\tresp.Body.Fault = &Fault{}\n\t\t\tresp.Body.Fault.Space = \"http://schemas.xmlsoap.org/soap/envelope/\"\n\t\t\tresp.Body.Fault.Code = \"soap:Server\"\n\t\t\tresp.Body.Fault.Detail = fmt.Sprintf(\"%%v\", r)\n\t\t\tresp.Body.Fault.String = fmt.Sprintf(\"%%v\", r)\n\t\t}\n\t\txml.NewEncoder(w).Encode(resp)\n\t}()\n\n\theader := r.Header.Get(\"Content-Type\")\n\tif strings.Index(header, \"application/soap+xml\") >= 0 {\n\t\tpanic(\"Could not find an appropriate Transport Binding to invoke.\")\n\t}\n\n\terr := xml.NewDecoder(r.Body).Decode(service)\n\tif err != nil {\n\t\tpanic(err)\n\t}\n\n\tfor i := 0; i < n; i++ {\n\t\tfield = val.Field(i)\n\t\tname = val.Type().Field(i).Name\n\t\tif field.Kind() != reflect.Ptr {\n\t\t\tcontinue\n\t\t}\n\t\tif field.IsNil() {\n\t\t\tcontinue\n\t\t}\n\t\tif field.IsValid() {\n\t\t\tfind = true\n\t\t\tbreak\n\t\t}\n\t}\n\n\tif !find {\n\t\tpanic(WSDLUndefinedError)\n\t} else {\n\t\tm := val.Addr().MethodByName(name + \"Func\")\n\t\tif !m.IsValid() {\n\t\t\tpanic(WSDLUndefinedError)\n\t\t}\n\n\t\tvals := m.Call([]reflect.Value{field})\n\t\tif vals[1].IsNil() {\n\t\t\treflect.ValueOf(&resp.Body).Elem().FieldByName(name).Set(vals[0])\n\t\t} else {\n\t\t\tpanic(vals[1].Interface())\n\t\t}\n\t}\n\n}\n\nfunc Endpoint(w http.ResponseWriter, r *http.Request) {\n\trequest := SOAPEnvelopeRequest{}\n\trequest.call(w, r)\n}\n")

	return nil
}

func capitalize(s string) string {
	if s == "" { return "" }
	return strings.ToUpper(s[:1]) + s[1:]
}

func uncapitalize(s string) string {
	if s == "" { return "" }
	return strings.ToLower(s[:1]) + s[1:]
}

func stripPrefix(s string) string {
	if i := strings.Index(s, ":"); i >= 0 {
		return s[i+1:]
	}
	return s
}
